package com.bookstore;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication // Contains @ComponentScan by default
public class BookstoreApplication {
    public static void main(String[] args) {
        SpringApplication.run(BookstoreApplication.class, args);
    }
}

// This service will be auto-discovered
package com.bookstore.service;

import org.springframework.stereotype.Service;

@Service // Marks this for component scanning
public class OrderService {
    public void processOrder(Long orderId) {
        System.out.println("Processing order: " + orderId);
    }
}

// This repository will also be found
package com.bookstore.repository;

import org.springframework.stereotype.Repository;

@Repository // Scanned and registered as a bean
public class CustomerRepository {
    public String findCustomerById(Long id) {
        return "Customer-" + id; // Simplified for demo
    }
}

// Main application in com.bookstore
