package com.bookstore;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.ComponentScan;

// String-based approach
@SpringBootApplication
@ComponentScan(basePackages = {
    "com.bookstore",      // Default root
    "com.shared.security", // Shared module
    "com.legacy.payment"   // Legacy integration
})
public class BookstoreApplication {
    public static void main(String[] args) {
        SpringApplication.run(BookstoreApplication.class, args);
    }
}

// Type-safe approach with marker classes
package com.shared.security;
public class SecurityConfig { } // Marker class

package com.legacy.payment;
public class PaymentModule { } // Marker class

@SpringBootApplication
@ComponentScan(basePackageClasses = {
    BookstoreApplication.class, // Scans com.bookstore
    SecurityConfig.class,       // Scans com.shared.security
    PaymentModule.class         // Scans com.legacy.payment
})
public class BookstoreApplication {
    // main method...
}

import org.springframework.context.annotation.Scope;
import org.springframework.stereotype.Service;
import org.springframework.stereotype.Component;
import org.springframework.web.context.annotation.RequestScope;

// Singleton scope (default) - one shared instance
@Service
public class OrderService {
    private final OrderRepository repo; // Immutable, thread-safe

    public OrderService(OrderRepository repo) {
        this.repo = repo;
    }

    public void processOrder(Long orderId) {
        // Stateless operation - safe for concurrent access
    }
}

// Prototype scope - new instance each time
@Component
@Scope("prototype")
public class ShoppingCart {
    private List<String> items = new ArrayList<>(); // Mutable state OK

    public void addItem(String item) {
        items.add(item); // Each user gets their own cart
    }
}

// Request scope - one per HTTP request
@Component
@RequestScope // Shorthand for @Scope("request")
public class RequestContext {
    private String userId; // Request-specific data
    private Instant requestTime = Instant.now();
}

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Service;
import org.springframework.stereotype.Repository;

// Single implementation - autowires by type
@Service
public class OrderService {
    private final OrderRepository orderRepository;

    @Autowired // Optional on constructors since Spring 4.3
    public OrderService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }
}

// Multiple implementations scenario
interface PaymentGateway { void process(double amount); }

@Service("stripeGateway")
class StripePaymentGateway implements PaymentGateway { }

@Service("paypalGateway")
class PaypalPaymentGateway implements PaymentGateway { }

@Service
public class CheckoutService {
    private final PaymentGateway paymentGateway;

    // Resolves by name match: field name = bean name
    public CheckoutService(PaymentGateway stripeGateway) {
        this.paymentGateway = stripeGateway; // Injects StripePaymentGateway
    }

    // Or use @Qualifier for explicit disambiguation
    public CheckoutService(@Qualifier("paypalGateway") PaymentGateway gateway) {
        this.paymentGateway = gateway; // Injects PaypalPaymentGateway
    }
}
